CREATE DATABASE IF NOT EXISTS triwear CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE triwear;
CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL, whatsapp VARCHAR(30) NOT NULL, address TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, description TEXT, image_url VARCHAR(500));
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NOT NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, description TEXT, material VARCHAR(160), price DECIMAL(14,2) NOT NULL, stock INT NOT NULL DEFAULT 0, is_featured TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE product_images (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, image_url VARCHAR(500) NOT NULL, alt_text VARCHAR(180), sort_order INT DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_variants (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, variant_type VARCHAR(30) NOT NULL, variant_name VARCHAR(100) NOT NULL, stock INT DEFAULT 0, extra_price DECIMAL(14,2) DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE sizes (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, display_name VARCHAR(80) NOT NULL, sort_order INT NOT NULL); 
CREATE TABLE product_sizes (product_id INT NOT NULL, size_id INT NOT NULL, stock INT NOT NULL DEFAULT 0, PRIMARY KEY(product_id,size_id), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY(size_id) REFERENCES sizes(id));
CREATE TABLE product_size_chart (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, label VARCHAR(80) NOT NULL, length_cm DECIMAL(7,1) NULL, width_cm DECIMAL(7,1) NULL, notes VARCHAR(180), sort_order INT DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE motifs (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, name VARCHAR(100) NOT NULL, stock INT DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE carts (id INT AUTO_INCREMENT PRIMARY KEY, session_token VARCHAR(128) NOT NULL UNIQUE, customer_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL);
CREATE TABLE cart_items (id INT AUTO_INCREMENT PRIMARY KEY, cart_id INT NOT NULL, product_id INT NOT NULL, selected_size_code VARCHAR(30) NOT NULL, selected_size_name VARCHAR(80) NOT NULL, selected_variant VARCHAR(100) NULL, selected_motif VARCHAR(100) NULL, quantity INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_cart_choice(cart_id,product_id,selected_size_code,selected_variant,selected_motif), FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE checkout_transactions (id INT AUTO_INCREMENT PRIMARY KEY, transaction_code VARCHAR(32) NOT NULL UNIQUE, customer_id INT NOT NULL, total DECIMAL(14,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE order_sequences (category_key VARCHAR(20) PRIMARY KEY, last_number INT NOT NULL DEFAULT 0);
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, checkout_transaction_id INT NOT NULL, order_number VARCHAR(24) NOT NULL UNIQUE, category_key VARCHAR(20) NOT NULL, customer_id INT NOT NULL, total DECIMAL(14,2) NOT NULL, payment_status ENUM('waiting_payment','waiting_verification','approved','rejected') NOT NULL DEFAULT 'waiting_payment', production_status ENUM('created','processing','completed') NOT NULL DEFAULT 'created', customer_note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, admin_confirmed_at TIMESTAMP NULL DEFAULT NULL, payment_expired_at TIMESTAMP NULL DEFAULT NULL, FOREIGN KEY(checkout_transaction_id) REFERENCES checkout_transactions(id), FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, product_id INT NOT NULL, product_name VARCHAR(180) NOT NULL, category_name VARCHAR(80) NOT NULL, unit_price DECIMAL(14,2) NOT NULL, quantity INT NOT NULL, selected_size_code VARCHAR(30) NOT NULL, selected_size_name VARCHAR(80) NOT NULL, selected_variant VARCHAR(100) NULL, selected_motif VARCHAR(100) NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE bank_accounts (id INT AUTO_INCREMENT PRIMARY KEY, bank_name VARCHAR(80) NOT NULL, account_name VARCHAR(120) NOT NULL, account_number VARCHAR(60) NOT NULL, is_active TINYINT(1) DEFAULT 1);
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, bank_account_id INT NULL, amount DECIMAL(14,2) NOT NULL, proof_path VARCHAR(500) NOT NULL, status ENUM('waiting_verification','approved','rejected') DEFAULT 'waiting_verification', submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, verified_at TIMESTAMP NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(bank_account_id) REFERENCES bank_accounts(id) ON DELETE SET NULL);
CREATE TABLE custom_orders (id INT AUTO_INCREMENT PRIMARY KEY, category_key VARCHAR(20) NOT NULL, customer_name VARCHAR(150), whatsapp VARCHAR(30), quantity INT, details TEXT, status VARCHAR(40) DEFAULT 'consultation', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE site_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL);

